def control(obs):
    t = obs['t']
    h = obs['hitch_deg']
    st = obs['status']
    dt = obs.get('dt', 0.1)
    v = obs['motion']['v_mps']
    if M['t0'] is None:
        M['t0'] = t
    if M['ph'] == 'rev' and st in ('JACKKNIFED', 'PINNED'):
        M['ph'] = 'fwd'
        M['t0'] = t
        M['d'] = 0.0
    if M['ph'] == 'fwd':
        M['d'] += max(0.0, v) * dt
        if M['d'] >= 1.0 or t - M['t0'] >= 8.0:
            M['ph'] = 'rev'
            M['t0'] = t
        else:
            return (0.0, 0.5, -23)
    steer = max(-12.0, min(12.0, 2.5 * (h + 4.0)))
    return (steer, -0.3, -23)

