def control(obs):
    global RECOVER_UNTIL
    t = obs.get('t', 0.0)
    h = obs.get('hitch_deg', 0.0)
    st = obs.get('status', '')
    if st in ('PINNED', 'JACKKNIFED') and RECOVER_UNTIL is None:
        RECOVER_UNTIL = t + 3.0
    if RECOVER_UNTIL is not None:
        if t < RECOVER_UNTIL:
            return (0.0, 0.5, 180)
        RECOVER_UNTIL = None
    T = -3.0
    steer = max(-30.0, min(30.0, 2.0 * (h - T)))
    return (steer, -0.5, 180)

