fwd_time = 0.0
phase = 'fwd'
last_t = None

def control(obs):
    global fwd_time, phase, last_t
    t = obs['t']
    dt = obs['dt'] if obs.get('dt') else 0.1
    v = obs['motion']['v_mps']
    if phase == 'fwd':
        if v > 0.3:
            fwd_time += dt
        if fwd_time >= 4.0:
            phase = 'rev'
    if phase == 'fwd':
        return (0.0, 0.8, -41.0)
    h = obs['hitch_deg']
    target = -1.0
    steer = max(-42.0, min(42.0, 2.5 * (h - target)))
    return (steer, -0.5, -41.0)

